// Bespoke icon set (assets/icons, generated by tools/mkicons.py). Nodspel ships its own copy of the sprite.
export const SPRITE='ui-icons.svg';
export function iconMarkup(name){return `<svg class="pr-ic" aria-hidden="true" focusable="false"><use href="${SPRITE}#${name}"/></svg>`;}
export function svgIcon(name){
  const NS='http://www.w3.org/2000/svg',svg=document.createElementNS(NS,'svg'),use=document.createElementNS(NS,'use');
  svg.setAttribute('class','pr-ic');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');
  use.setAttribute('href',`${SPRITE}#${name}`);svg.append(use);svg.dataset.icon=name;return svg;
}
// Icon + text in one element; no-op when unchanged (called every frame for some labels).
export function setIconText(el,name,text){
  const t=name&&text?` ${text}`:text,key=`${name}|${text}`;
  if(el.dataset.it===key&&el.lastChild?.nodeValue===t&&(!name||el.firstChild?.dataset?.icon===name))return;
  el.dataset.it=key;el.replaceChildren(...(name?[svgIcon(name)]:[]),document.createTextNode(t));
}
